// Classify the error into a category for routing.
// Categories: transient, data, auth, external, unknown
const msg = ($json.error_message || '').toLowerCase();
const stack = ($json.error_stack || '').toLowerCase();
const code = ($json.error_code || '').toString().toLowerCase();
const text = `${msg} ${stack} ${code}`;

let category = 'unknown';
let severity = 'warning';
let retryable = false;

// Transient: network blips, timeouts, connection resets, 5xx
if (
  text.includes('etimedout') ||
  text.includes('econnreset') ||
  text.includes('econnrefused') ||
  text.includes('enotfound') ||
  text.includes('socket hang up') ||
  text.includes('timeout') ||
  text.includes('503') ||
  text.includes('502') ||
  text.includes('504') ||
  text.includes('service unavailable')
) {
  category = 'transient';
  severity = 'warning';
  retryable = true;
}
// Auth: 401, 403, token expired, unauthorized
else if (
  text.includes('401') ||
  text.includes('403') ||
  text.includes('unauthorized') ||
  text.includes('forbidden') ||
  text.includes('token expired') ||
  text.includes('invalid_grant') ||
  text.includes('invalid token')
) {
  category = 'auth';
  severity = 'critical';
  retryable = true; // retry once after token refresh
}
// Rate limit: 429
else if (text.includes('429') || text.includes('rate limit') || text.includes('too many requests')) {
  category = 'transient';
  severity = 'warning';
  retryable = true;
}
// Data: validation errors, schema mismatch, missing fields
else if (
  text.includes('validation') ||
  text.includes('schema') ||
  text.includes('required field') ||
  text.includes('invalid input') ||
  text.includes('not null') ||
  text.includes('foreign key')
) {
  category = 'data';
  severity = 'error';
  retryable = false;
}
// External: third-party API returned an error (excluding 5xx already handled)
else if (
  text.includes('whatsapp') ||
  text.includes('sendgrid') ||
  text.includes('razorpay') ||
  text.includes('google') ||
  text.includes('openai') ||
  text.includes('anthropic')
) {
  category = 'external';
  severity = 'error';
  retryable = true;
}

return {
  json: {
    ...$json,
    category,
    severity,
    retryable,
    classified_at: new Date().toISOString()
  }
};

